ITEMS += [
    bq(U, EX51, 'EX5.1', '1', 'Sum the series up to the indicated terms: 1<sup>2</sup> + 2<sup>2</sup> + 3<sup>2</sup> + … + 10<sup>2</sup>.',
       '385.',
       'Use Σ<sub>k=1</sub><sup>n</sup> k<sup>2</sup> = n(n + 1)(2n + 1)/6 with n = 10: S = 10·11·21/6 = 5·11·7 = 385.', 171),
    bq(U, EX51, 'EX5.1', '2', 'Sum the series up to the indicated terms: 1<sup>3</sup> + 2<sup>3</sup> + 3<sup>3</sup> + … + 15<sup>3</sup>.',
       '14400.',
       'Use Σ<sub>k=1</sub><sup>n</sup> k<sup>3</sup> = [n(n + 1)/2]<sup>2</sup> with n = 15: S = [15·16/2]<sup>2</sup> = 120<sup>2</sup> = 14400.', 171),
    bq(U, EX51, 'EX5.1', '3', 'Sum the series up to n terms: 1<sup>2</sup> + 3<sup>2</sup> + 5<sup>2</sup> + …',
       'n(2n − 1)(2n + 1)/3.',
       'The rth term is (2r − 1)<sup>2</sup> = 4r<sup>2</sup> − 4r + 1. So S = 4Σr<sup>2</sup> − 4Σr + n = 4n(n + 1)(2n + 1)/6 − 4n(n + 1)/2 + n = n[(2/3)(n + 1)(2n + 1) − 2(n + 1) + 1] = n(4n<sup>2</sup> − 1)/3 = n(2n − 1)(2n + 1)/3.', 171),
    bq(U, EX51, 'EX5.1', '4', 'Sum the series up to n terms: 2<sup>2</sup> + 4<sup>2</sup> + 6<sup>2</sup> + 8<sup>2</sup> + …',
       '2n(n + 1)(2n + 1)/3.',
       'The rth term is (2r)<sup>2</sup> = 4r<sup>2</sup>. Hence S = 4Σr<sup>2</sup> = 4n(n + 1)(2n + 1)/6 = 2n(n + 1)(2n + 1)/3.', 171),
    bq(U, EX51, 'EX5.1', '5', 'Sum the series up to n terms: 1<sup>3</sup> + 3<sup>3</sup> + 5<sup>3</sup> + …',
       'n<sup>2</sup>(2n<sup>2</sup> − 1).',
       'The rth term is (2r − 1)<sup>3</sup> = 8r<sup>3</sup> − 12r<sup>2</sup> + 6r − 1. So S = 8[n(n + 1)/2]<sup>2</sup> − 12n(n + 1)(2n + 1)/6 + 6n(n + 1)/2 − n = 2n<sup>2</sup>(n + 1)<sup>2</sup> − 2n(n + 1)(2n + 1) + 3n(n + 1) − n = n[2n(n + 1)<sup>2</sup> − 2(n + 1)(2n + 1) + 3(n + 1) − 1] = n(2n<sup>3</sup> − n) = n<sup>2</sup>(2n<sup>2</sup> − 1).', 171),
    bq(U, EX51, 'EX5.1', '6', 'Sum the series up to n terms: 2 × 1<sup>2</sup> + 5 × 2<sup>2</sup> + 8 × 3<sup>2</sup> + …',
       'n(n + 1)(9n<sup>2</sup> + 5n − 2)/12.',
       'The rth term is (3r − 1)r<sup>2</sup> = 3r<sup>3</sup> − r<sup>2</sup>. So S = 3[n(n + 1)/2]<sup>2</sup> − n(n + 1)(2n + 1)/6 = n(n + 1)/12·[9n(n + 1) − 2(2n + 1)] = n(n + 1)(9n<sup>2</sup> + 9n − 4n − 2)/12 = n(n + 1)(9n<sup>2</sup> + 5n − 2)/12.', 171),
    bq(U, EX51, 'EX5.1', '7', 'Sum the series up to n terms: 1 + (1 + 2) + (1 + 2 + 3) + …',
       'n(n + 1)(n + 2)/6.',
       'The rth bracket is 1 + 2 + … + r = r(r + 1)/2 = (r<sup>2</sup> + r)/2. So S = ½(Σr<sup>2</sup> + Σr) = ½[n(n + 1)(2n + 1)/6 + n(n + 1)/2] = n(n + 1)/12·[(2n + 1) + 3] = n(n + 1)(2n + 4)/12 = n(n + 1)(n + 2)/6.', 171),
    bq(U, EX51, 'EX5.1', '8', 'Sum the series up to n terms: 2 + (2 + 5) + (2 + 5 + 8) + …',
       'n(n + 1)<sup>2</sup>/2.',
       'The rth bracket is the sum of r terms of the A.P. 2, 5, 8, …: r/2[2·2 + (r − 1)3] = r(3r + 1)/2. So S = ½(3Σr<sup>2</sup> + Σr) = ½[n(n + 1)(2n + 1)/2 + n(n + 1)/2] = n(n + 1)(2n + 2)/4 = n(n + 1)<sup>2</sup>/2.', 171),

    bq(U, EX51, 'EX5.1', '9(i)', 'Find the sum of n terms of the series whose nth term is 3n<sup>2</sup> + n + 1.',
       'n(n<sup>2</sup> + 2n + 2).',
       'S = 3Σn<sup>2</sup> + Σn + n = 3n(n + 1)(2n + 1)/6 + n(n + 1)/2 + n = n(n + 1)(2n + 1)/2 + n(n + 1)/2 + n = n[(n + 1)(2n + 1) + (n + 1)]/2 + n = n(n + 1)<sup>2</sup> + n = n(n<sup>2</sup> + 2n + 2).', 171),
    bq(U, EX51, 'EX5.1', '9(ii)', 'Find the sum of n terms of the series whose nth term is n<sup>2</sup> + 4n + 1.',
       'n(2n<sup>2</sup> + 15n + 19)/6.',
       'S = Σn<sup>2</sup> + 4Σn + n = n(n + 1)(2n + 1)/6 + 4n(n + 1)/2 + n = n[(n + 1)(2n + 1) + 12(n + 1) + 6]/6 = n(2n<sup>2</sup> + 3n + 1 + 12n + 12 + 6)/6 = n(2n<sup>2</sup> + 15n + 19)/6.', 171),
    bq(U, EX51, 'EX5.1', '9(iii)', 'Find the sum of n terms of the series whose nth term is n<sup>3</sup> + 3n<sup>2</sup> + 2n + 1.',
       'n(n<sup>3</sup> + 6n<sup>2</sup> + 11n + 10)/4.',
       'S = Σn<sup>3</sup> + 3Σn<sup>2</sup> + 2Σn + n = n<sup>2</sup>(n + 1)<sup>2</sup>/4 + 3n(n + 1)(2n + 1)/6 + 2n(n + 1)/2 + n = n<sup>2</sup>(n + 1)<sup>2</sup>/4 + n(n + 1)(2n + 1)/2 + n(n + 1) + n = n/4·[n(n + 1)<sup>2</sup> + 2(n + 1)(2n + 1) + 4(n + 1) + 4] = n/4·(n<sup>3</sup> + 2n<sup>2</sup> + n + 4n<sup>2</sup> + 6n + 2 + 4n + 4 + 4) = n(n<sup>3</sup> + 6n<sup>2</sup> + 11n + 10)/4.', 171),

    bq(U, EX51, 'EX5.1', '10(i)', 'Find the sum of the first forty six natural numbers starting from 10.',
       '1495.',
       'Read literally, the series has 46 terms: 10 + 11 + … + 55. S = 46/2·(10 + 55) = 23 × 65 = 1495. The printed key gives 1036, which is 10 + 11 + … + 46 (37 terms); that treats 46 as the last term rather than the number of terms. The literal reading gives 1495.', 172),
    bq(U, EX51, 'EX5.1', '10(ii)', 'Find the sum of the last 12 terms of the series: 1 + 2 + 3 + … + 39.',
       '402.',
       'The last 12 terms are 28, 29, …, 39. Their sum is S = 12/2·(28 + 39) = 6 × 67 = 402. Equivalently S<sub>39</sub> − S<sub>27</sub> = 39·40/2 − 27·28/2 = 780 − 378 = 402.', 172),
    bq(U, EX51, 'EX5.1', '11', 'Find the sum of the 9th to 21st terms of the series of squares of the first n natural numbers.',
       '3107.',
       'Σ<sub>k=9</sub><sup>21</sup> k<sup>2</sup> = Σ<sub>k=1</sub><sup>21</sup> k<sup>2</sup> − Σ<sub>k=1</sub><sup>8</sup> k<sup>2</sup> = 21·22·43/6 − 8·9·17/6 = 3311 − 204 = 3107.', 172),
    bq(U, EX51, 'EX5.1', '12', 'Find the sum of the last 12 terms of the series of cubes of the first 30 natural numbers.',
       '186984.',
       'The last 12 cubes are 19<sup>3</sup> + 20<sup>3</sup> + … + 30<sup>3</sup>. So S = [30·31/2]<sup>2</sup> − [18·19/2]<sup>2</sup> = 465<sup>2</sup> − 171<sup>2</sup> = 216225 − 29241 = 186984.', 172),
]

# ============================================================== Exercise 5.2 (pdf 174)
ITEMS += [
    bq(U, EX52, 'EX5.2', '1', 'Sum the series up to the indicated terms: 1·2 + 2·2<sup>2</sup> + 3·2<sup>3</sup> + 4·2<sup>4</sup> + … to 50 terms.',
       '98·2<sup>50</sup> + 2.',
       'Let S = Σ<sub>k=1</sub><sup>50</sup> k·2<sup>k</sup>. Then 2S = Σ<sub>k=1</sub><sup>50</sup> k·2<sup>k+1</sup>. Subtracting, 2S − S = 50·2<sup>51</sup> − (2 + 2<sup>2</sup> + … + 2<sup>50</sup>) = 50·2<sup>51</sup> − 2(2<sup>50</sup> − 1) = 50·2<sup>51</sup> − 2<sup>51</sup> + 2 = 49·2<sup>51</sup> + 2 = 98·2<sup>50</sup> + 2.', 174),
    bq(U, EX52, 'EX5.2', '2', 'Sum the series up to the indicated terms: 1 + 2·5 + 3·5<sup>2</sup> + 4·5<sup>3</sup> + … to 30 terms.',
       '1/16 + (119/16)·5<sup>30</sup>.',
       'Here the dot denotes multiplication, so r = 5 and S = 1 + 2·5 + 3·5<sup>2</sup> + … + 30·5<sup>29</sup>. Then 5S = 5 + 2·5<sup>2</sup> + … + 29·5<sup>29</sup> + 30·5<sup>30</sup>. Subtracting: −4S = 1 + 5 + 5<sup>2</sup> + … + 5<sup>29</sup> − 30·5<sup>30</sup> = (5<sup>30</sup> − 1)/4 − 30·5<sup>30</sup>. Thus 4S = 30·5<sup>30</sup> − (5<sup>30</sup> − 1)/4 = (119·5<sup>30</sup> + 1)/4 and S = (119·5<sup>30</sup> + 1)/16 = 1/16 + (119/16)·5<sup>30</sup>.', 174),
    bq(U, EX52, 'EX5.2', '3', 'Sum the series up to the indicated terms: 1 + 3/2 + 5/2<sup>2</sup> + 7/2<sup>3</sup> + … to 25 terms.',
       '6 − 53/2<sup>24</sup>.',
       'The rth term is (2r − 1)/2<sup>r−1</sup> with r = 1, …, 25. Let S be the sum; then S/2 = 1/2 + 3/2<sup>2</sup> + … + 47/2<sup>24</sup> + 49/2<sup>25</sup>. Subtracting: S/2 = 1 + (1 + 1/2 + … + 1/2<sup>23</sup>) − 49/2<sup>25</sup> = 3 − 2/2<sup>24</sup> − 49/2<sup>25</sup> = 3 − 53/2<sup>25</sup>. Hence S = 6 − 53/2<sup>24</sup>.', 174),
    bq(U, EX52, 'EX5.2', '4', 'Sum the series up to n terms: 1 + 8/5 + 15/5<sup>2</sup> + 22/5<sup>3</sup> + …',
       '(5/4)·[11/4 − 7/(4·5<sup>n−1</sup>) − (7n − 6)/5<sup>n</sup>].',
       'This is an A.G. series with a = 1, d = 7, r = 1/5. Use S<sub>n</sub> = a/(1 − r) + dr/(1 − r)<sup>2</sup> − dr<sup>n</sup>/(1 − r)<sup>2</sup> − [a + (n − 1)d]r<sup>n</sup>/(1 − r): S<sub>n</sub> = 5/4 + 35/16 − 35/(16·5<sup>n−1</sup>) − (7n − 6)/(4·5<sup>n−1</sup>) = 55/16 − 35/(16·5<sup>n−1</sup>) − (7n − 6)/(4·5<sup>n−1</sup>) = (5/4)·[11/4 − 7/(4·5<sup>n−1</sup>) − (7n − 6)/5<sup>n</sup>].', 174),
    bq(U, EX52, 'EX5.2', '5', 'Find the sum to infinity of the series: 1 + 4/3 + 9/3<sup>2</sup> + 14/3<sup>3</sup> + 19/3<sup>4</sup> + …',
       '17/4.',
       'Take the first term separately: S = 1 + T, where T = 4/3 + 9/3<sup>2</sup> + 14/3<sup>3</sup> + … is an A.G. series with first term a = 4/3, ratio r = 1/3 and numerator difference 5, i.e. d = 5/3. Sum to infinity of T is a/(1 − r) + dr/(1 − r)<sup>2</sup> = (4/3)/(2/3) + (5/3)(1/3)/(4/9) = 2 + 5/4 = 13/4. Hence S = 1 + 13/4 = 17/4.', 174),
    bq(U, EX52, 'EX5.2', '6', 'Find the sum to infinity of the series: 1 + 9a + 17a<sup>2</sup> + 25a<sup>3</sup> + … where |a| &lt; 1.',
       '(1 + 7a)/(1 − a)<sup>2</sup>.',
       'Here a<sub>1</sub> = 1, d = 8 and r = a with |a| &lt; 1. Sum to infinity = a<sub>1</sub>/(1 − r) + dr/(1 − r)<sup>2</sup> = 1/(1 − a) + 8a/(1 − a)<sup>2</sup> = (1 − a + 8a)/(1 − a)<sup>2</sup> = (1 + 7a)/(1 − a)<sup>2</sup>.', 174),
    bq(U, EX52, 'EX5.2', '7', 'Find the sum to infinity of the series: 1 + 4b + 7b<sup>2</sup> + 10b<sup>3</sup> + … where |b| &lt; 1.',
       '(1 + 2b)/(1 − b)<sup>2</sup>.',
       'Here a<sub>1</sub> = 1, d = 3 and r = b with |b| &lt; 1. Sum to infinity = 1/(1 − b) + 3b/(1 − b)<sup>2</sup> = (1 − b + 3b)/(1 − b)<sup>2</sup> = (1 + 2b)/(1 − b)<sup>2</sup>.', 174),
    bq(U, EX52, 'EX5.2', '8', 'Find the sum to infinity of the series: 1 + 4/4 + 7/4<sup>2</sup> + 10/4<sup>3</sup> + …',
       '8/3.',
       'Here a<sub>1</sub> = 1, d = 3 and r = 1/4. Sum = 1/(1 − 1/4) + 3(1/4)/(1 − 1/4)<sup>2</sup> = 4/3 + (3/4)/(9/16) = 4/3 + (3/4)(16/9) = 4/3 + 4/3 = 8/3.', 174),
    bq(U, EX52, 'EX5.2', '9', 'Find the sum to infinity of the series: 1 + 5/3 + 9/3<sup>2</sup> + 13/3<sup>3</sup> + …',
       '9/2.',
       'Here a<sub>1</sub> = 1, d = 4 and r = 1/3. Sum = 1/(1 − 1/3) + 4(1/3)/(1 − 1/3)<sup>2</sup> = 3/2 + (4/3)/(4/9) = 3/2 + 3 = 9/2.', 174),
    bq(U, EX52, 'EX5.2', '10', 'Find the sum to infinity of the series: 1 + 5a + 9a<sup>2</sup> + 13a<sup>3</sup> + … where |a| &lt; 1.',
       '(1 + 3a)/(1 − a)<sup>2</sup>.',
       'Here a<sub>1</sub> = 1, d = 4 and r = a with |a| &lt; 1. Sum to infinity = 1/(1 − a) + 4a/(1 − a)<sup>2</sup> = (1 − a + 4a)/(1 − a)<sup>2</sup> = (1 + 3a)/(1 − a)<sup>2</sup>.', 174),
]

# ============================================================== Exercise 5.3 (pdf 178)
ITEMS += [
    bq(U, EX53, 'EX5.3', '1', 'Find the sum of the series: 3 + 6 + 12 + 21 + 33 + … to n terms.',
       'n(n<sup>2</sup> + 5)/2.',
       'Differences of consecutive terms are 3, 6, 9, 12, … an A.P. with first term 3 and common difference 3. So a<sub>n</sub> = 3 + Σ<sub>r=1</sub><sup>n−1</sup> 3r = 3 + 3n(n − 1)/2 = (3n<sup>2</sup> − 3n + 6)/2. Then S<sub>n</sub> = (3/2)Σn<sup>2</sup> − (3/2)Σn + 3n = 3n(n + 1)(2n + 1)/12 − 3n(n + 1)/4 + 3n = n[(n + 1)(2n + 1) − 3(n + 1) + 12]/4 = n(2n<sup>2</sup> + 10)/4 = n(n<sup>2</sup> + 5)/2.', 178),
    bq(U, EX53, 'EX5.3', '2', 'Find the sum of the series: 5 + 10 + 17 + 26 + 37 + … to n terms.',
       'n(2n<sup>2</sup> + 9n + 19)/6.',
       'Differences are 5, 7, 9, 11, … an A.P. with first term 5 and common difference 2. So a<sub>n</sub> = 5 + (n − 1)/2·[2·5 + (n − 2)2] = 5 + (n − 1)(n + 3) = n<sup>2</sup> + 2n + 2. Then S<sub>n</sub> = Σn<sup>2</sup> + 2Σn + 2n = n(n + 1)(2n + 1)/6 + n(n + 1) + 2n = n[(n + 1)(2n + 1) + 6(n + 1) + 12]/6 = n(2n<sup>2</sup> + 9n + 19)/6.', 178),
    bq(U, EX53, 'EX5.3', '3', 'Find the sum of the series: 7 + 14 + 26 + 43 + 65 + … to n terms.',
       'n(5n<sup>2</sup> + 6n + 31)/6.',
       'Differences are 7, 12, 17, 22, … an A.P. with first term 7 and common difference 5. So a<sub>n</sub> = 7 + (n − 1)/2·[2·7 + (n − 2)5] = 7 + (n − 1)(5n + 4)/2 = (5n<sup>2</sup> − n + 10)/2. Then S<sub>n</sub> = (5/2)Σn<sup>2</sup> − (1/2)Σn + 5n = 5n(n + 1)(2n + 1)/12 − n(n + 1)/4 + 5n = n[5(n + 1)(2n + 1) − 3(n + 1) + 60]/12 = n(10n<sup>2</sup> + 12n + 62)/12 = n(5n<sup>2</sup> + 6n + 31)/6.', 178),
    bq(U, EX53, 'EX5.3', '4', 'Find the sum of the series: 3 + 6 + 15 + 42 + 123 + … to n terms.',
       '[6n + 3(3<sup>n</sup> − 1)]/4.',
       'Differences are 3, 9, 27, 81, … a G.P. with first term 3 and ratio 3. So a<sub>n</sub> = 3 + 3(3<sup>n−1</sup> − 1)/(3 − 1) = 3 + (3<sup>n</sup> − 3)/2 = (3<sup>n</sup> + 3)/2. Then S<sub>n</sub> = ½Σ3<sup>n</sup> + (3/2)n = ½·3(3<sup>n</sup> − 1)/2 + 3n/2 = [3(3<sup>n</sup> − 1) + 6n]/4 = [6n + 3(3<sup>n</sup> − 1)]/4.', 178),
    bq(U, EX53, 'EX5.3', '5', 'Find the sum of the series: 7 + 14 + 45 + 100 + 179 + … to n terms.',
       'n(8n<sup>2</sup> − 17n + 23)/2.',
       'Differences are 7, 31, 55, 79, … an A.P. with first term 7 and common difference 24. So a<sub>n</sub> = 7 + (n − 1)/2·[2·7 + (n − 2)24] = 7 + (n − 1)(12n − 17) = 12n<sup>2</sup> − 29n + 24. Then S<sub>n</sub> = 12Σn<sup>2</sup> − 29Σn + 24n = 2n(n + 1)(2n + 1) − (29/2)n(n + 1) + 24n = n[4(n + 1)(2n + 1) − 29(n + 1) + 48]/2 = n(8n<sup>2</sup> − 17n + 23)/2.', 178),
    bq(U, EX53, 'EX5.3', '6', 'Find the sum of the series: 3 + 6 + 21 + 96 + 471 + … to n terms.',
       '[36n + 3(5<sup>n</sup> − 1)]/16.',
       'Differences are 3, 15, 75, 375, … a G.P. with first term 3 and ratio 5. So a<sub>n</sub> = 3 + 3(5<sup>n−1</sup> − 1)/(5 − 1) = 3 + 3(5<sup>n−1</sup> − 1)/4 = (9 + 3·5<sup>n−1</sup>)/4. Then S<sub>n</sub> = (9/4)n + (3/4)·(5<sup>n</sup> − 1)/4 = [36n + 3(5<sup>n</sup> − 1)]/16. The printed key reads 3(5<sup>n</sup> − 15), which gives 6/16 = 3/8 for n = 1 instead of the first term 3; this is a key typo for 3(5<sup>n</sup> − 1).', 178),
]

# ============================================================== Exercise 5.4 (pdf 181)
ITEMS += [
    bq(U, EX54, 'EX5.4', '1', 'Find the sum of the series: 1/(1·3) + 1/(3·5) + 1/(5·7) + … to n terms.',
       'n/(2n + 1).',
       'The kth term is 1/[(2k − 1)(2k + 1)] = ½[1/(2k − 1) − 1/(2k + 1)]. Hence S<sub>n</sub> = ½[(1 − 1/3) + (1/3 − 1/5) + … + (1/(2n − 1) − 1/(2n + 1))] = ½[1 − 1/(2n + 1)] = n/(2n + 1).', 181),
    bq(U, EX54, 'EX5.4', '2', 'Find the sum of the series: 1/(1·5) + 1/(5·9) + 1/(9·13) + … to n terms.',
       'n/(4n + 1).',
       'The kth term is 1/[(4k − 3)(4k + 1)] = ¼[1/(4k − 3) − 1/(4k + 1)]. Hence S<sub>n</sub> = ¼[(1 − 1/5) + (1/5 − 1/9) + … + (1/(4n − 3) − 1/(4n + 1))] = ¼[1 − 1/(4n + 1)] = n/(4n + 1).', 181),
    bq(U, EX54, 'EX5.4', '3', 'Find the sum of the series: 1/(1·5·9) + 1/(5·9·13) + 1/(9·13·17) + … to infinity.',
       '1/40.',
       'The kth term is 1/[(4k − 3)(4k + 1)(4k + 5)]. Put x = 4k − 3, so the term is 1/[x(x + 4)(x + 8)] = (1/32)[1/x − 2/(x + 4) + 1/(x + 8)]. Summing from k = 1 to n and cancelling, S<sub>n</sub> = (1/32)[1 − 1/5 − 1/(4n + 1) + 1/(4n + 5)]. As n → ∞, S = (1/32)(1 − 1/5) = (1/32)(4/5) = 1/40.', 181),
    bq(U, EX54, 'EX5.4', '4', 'Find the sum of the series: 1/(1·4·7) + 1/(4·7·10) + 1/(7·10·13) + … to infinity.',
       '1/24.',
       'The kth term is 1/[(3k − 2)(3k + 1)(3k + 4)]. With x = 3k − 2, 1/[x(x + 3)(x + 6)] = (1/18)[1/x − 2/(x + 3) + 1/(x + 6)]. Summing to n and cancelling, S<sub>n</sub> = (1/18)[1 − 1/4 − 1/(3n + 1) + 1/(3n + 4)]. As n → ∞, S = (1/18)(3/4) = 1/24.', 181),
    bq(U, EX54, 'EX5.4', '5', 'Find the sum of the series: Σ<sub>k=1</sub><sup>∞</sup> 1/(4k<sup>2</sup> − 1).',
       '1/2.',
       '4k<sup>2</sup> − 1 = (2k − 1)(2k + 1), so the kth term is ½[1/(2k − 1) − 1/(2k + 1)]. Hence the partial sum to n terms is ½[1 − 1/(2n + 1)], and as n → ∞ the sum is ½·1 = 1/2.', 181),
    bq(U, EX54, 'EX5.4', '6', 'Find the sum of the series: Σ<sub>k=1</sub><sup>n</sup> 1/(9k<sup>2</sup> + 3k − 2).',
       'n/[2(3n + 2)].',
       '9k<sup>2</sup> + 3k − 2 = (3k − 1)(3k + 2), so the kth term is ⅓[1/(3k − 1) − 1/(3k + 2)]. Hence S<sub>n</sub> = ⅓[(1/2 − 1/5) + (1/5 − 1/8) + … + (1/(3n − 1) − 1/(3n + 2))] = ⅓[1/2 − 1/(3n + 2)] = ⅓·3n/[2(3n + 2)] = n/[2(3n + 2)]. For n = 1 this is 1/10, the actual first term. The printed key gives n/[6(3n + 2)] (which would give 1/30 for n = 1), so the 6 is a key typo for 2.', 181),
    bq(U, EX54, 'EX5.4', '7', 'Find the sum of the series: Σ<sub>k=2</sub><sup>∞</sup> 1/(k<sup>2</sup> − 1).',
       '3/4.',
       '1/(k<sup>2</sup> − 1) = 1/[(k − 1)(k + 1)] = ½[1/(k − 1) − 1/(k + 1)]. The sum to n terms is ½[(1 − 1/3) + (1/2 − 1/4) + (1/3 − 1/5) + … + (1/(n − 1) − 1/(n + 1))] = ½[1 + 1/2 − 1/n − 1/(n + 1)]. As n → ∞, S = ½(3/2) = 3/4.', 181),
    bq(U, EX54, 'EX5.4', '8', 'Find the sum of the series: Σ<sub>k=2</sub><sup>n</sup> 1/(k<sup>2</sup> − k).',
       '(n − 1)/n.',
       '1/(k<sup>2</sup> − k) = 1/[k(k − 1)] = 1/(k − 1) − 1/k. Hence S<sub>n</sub> = (1 − 1/2) + (1/2 − 1/3) + … + (1/(n − 1) − 1/n) = 1 − 1/n = (n − 1)/n.', 181),
]

